    "type": "bulleted_list",
    "content": "",
    "items": [
      {
        "content": "Capital Markets Lending Desk: Ensures compliance with all requirements during transaction onboarding and ongoing monitoring."
      },
      {
        "content": "Credit Risk Management: Defines eligibility, reviews collateral profiles, and approves exceptions."
      },
      {
        "content": "Market Risk: Provides valuation oversight, stress testing guidance, and concentration monitoring."
      },
      {
        "content": "Legal: Confirms enforceability of collateral rights and reviews all non-standard arrangements."
      },
      {
        "content": "Operations: Performs daily margining, valuation updates, and reporting."
      }
    ]
  },
